-- seed.sql
-- Limpia y repuebla la base con datos de prueba. Seguro de ejecutar
-- varias veces: siempre deja la base en el mismo estado conocido.
--
-- Generado con una semilla fija (random.seed(42)) para que el contenido
-- sea reproducible: volver a generarlo produce exactamente los mismos datos.
-- Volumen deliberadamente alto (~1000+ tareas) para que las consultas de
-- inteligencia de negocio agrupadas por día (preguntas 2 y 4) devuelvan
-- tasas con variedad real, en vez de solo 0% o 100% por falta de muestra.
--
-- Los ocho usuarios de prueba usan la contraseña en texto plano:
-- Test.1234

BEGIN;

-- 1. Limpieza total, en cualquier orden (CASCADE resuelve las FK) y
--    reinicio de los contadores de identidad para que los ids vuelvan a 1.
TRUNCATE TABLE tarea_etiquetas, tareas, etiquetas, categorias, usuarios
  RESTART IDENTITY CASCADE;

